export const API_EXTENSIONS: ApiExtension[] = [{"class": "CurrentUserExtensions", "path": "src/Kindi.API.Application/Common/Extensions/CurrentUserExtensions.cs", "doc": "", "methods": [{"returnType": "bool", "name": "IsInRole", "generics": "", "params": ["this ICurrentUserService currentUser", "UserRole role"], "doc": "Kiểm tra người dùng hiện tại có vai trò <paramref name=\"role\"/> không — claim vai trò trong JWT lưu dạng số nên so qua <see cref=\"RoleConstants\"/>. SuperAdmin phải có nhánh riêng: thiếu nhánh này thì mọi lời gọi hỏi SuperAdmin sẽ rơi vào nhánh mặc định và kiểm tra nhầm role User (đã gặp: cờ bảo vệ tài khoản SuperAdmin không chạy)."}]}, {"class": "PagingExtensions", "path": "src/Kindi.API.Application/Common/Extensions/PagingExtensions.cs", "doc": "Extension methods phân trang cho IQueryable — trả về PagedList.", "methods": [{"returnType": "async Task<PagedList<T>>", "name": "ToPagedListAsync", "generics": "T", "params": ["this IQueryable<T> source", "int pageNumber", "int pageSize", "CancellationToken cancellationToken = default"], "doc": "Phân trang đơn giản (count + PageBy + ToListAsync)."}, {"returnType": "async Task<PagedList<T>>", "name": "ToPagedListAsync", "generics": "T", "params": ["this IQueryable<T> source", "int pageNumber", "int pageSize", "string? sortBy", "string? sortOrder = null", "string? defaultSortBy = null", "CancellationToken cancellationToken = default"], "doc": "Sort động trước, rồi phân trang — tiện cho query theo query-param."}, {"returnType": "async Task<PagedList<T>>", "name": "ToPagedListAsync", "generics": "T", "params": ["this IQueryable<T> source", "SortableQueryRequest request", "string? defaultSortBy = null", "CancellationToken cancellationToken = default"], "doc": "Phân trang + sort động từ SortableQueryRequest (chuẩn cho DTO kế thừa base)."}, {"returnType": "async Task<PagedList<T>>", "name": "ToPagedListAsync", "generics": "T", "params": ["this IQueryable<T> source", "int pageNumber", "int pageSize", "Func<IQueryable<T>, IQueryable<T>>? sortFunc", "CancellationToken cancellationToken = default"], "doc": "Sort tùy biến theo delegate (kiểu sortOrder: o => o.OrderByDescending(x => x.CreatedAt)), rồi phân trang."}, {"returnType": "async Task<PagedList<T>>", "name": "ToPagedListAsync", "generics": "T, TKey", "params": ["this IQueryable<T> source", "int pageNumber", "int pageSize", "Expression<Func<T, TKey>> sortBy", "string? sortOrder = \"asc\"", "CancellationToken cancellationToken = default"], "doc": "Sort theo expression (kiểu sortBy: e => e.CreatedAt) + sortOrder, rồi phân trang."}]}, {"class": "QueryableExtensions", "path": "src/Kindi.API.Application/Common/Extensions/QueryableExtensions.cs", "doc": "Extension methods cho IQueryable — dùng free-style query cầu kỳ.", "methods": [{"returnType": "IQueryable<T>", "name": "WhereIf", "generics": "T", "params": ["this IQueryable<T> source", "bool condition", "Expression<Func<T, bool>> predicate"], "doc": "Áp predicate khi condition đúng (dùng cho filter tùy chọn từ query param)."}, {"returnType": "IQueryable<T>", "name": "WhereIfNotNull", "generics": "T", "params": ["this IQueryable<T> source", "Expression<Func<T, bool>>? predicate"], "doc": "Áp predicate nếu không null (dùng cho expression xây dựng dần)."}, {"returnType": "IQueryable<T>", "name": "WhereIfNotNull", "generics": "T, TValue", "params": ["this IQueryable<T> source", "TValue? value", "Expression<Func<T, bool>> predicate"], "doc": "Áp predicate khi giá trị filter khác null/default (free-style filter theo DTO)."}, {"returnType": "IQueryable<T>", "name": "PageBy", "generics": "T", "params": ["this IQueryable<T> source", "int pageNumber", "int pageSize"], "doc": "Skip/Take theo trang."}, {"returnType": "IQueryable<T>", "name": "OrderByDynamic", "generics": "T", "params": ["this IQueryable<T> source", "string? sortBy", "string? sortOrder = null", "string? defaultSortBy = null"], "doc": "Sort động theo chuỗi (vd \"CreatedAt\" + \"desc\"). Tên cột được validate qua reflection để tránh SQL injection / lỗi runtime; nếu không hợp lệ sẽ fallback về defaultSortBy. Mặc định mới nhất trước: chỉ sắp xếp tăng dần khi client truyền rõ sortOrder = \"asc\"."}, {"returnType": "IQueryable<T>", "name": "SortBy", "generics": "T, TKey", "params": ["this IQueryable<T> source", "Expression<Func<T, TKey>> keySelector", "string? sortOrder = \"asc\""], "doc": "Sort theo expression, kiểu trỏ thẳng (vd: e => e.CreatedAt). sortOrder: \"asc\" | \"desc\"."}, {"returnType": "IQueryable<T>", "name": "ApplySort", "generics": "T", "params": ["this IQueryable<T> source", "Func<IQueryable<T>, IQueryable<T>>? sortFunc"], "doc": "Sort tùy biến theo delegate — kiểu sortOrder truyền thẳng Func<IQueryable, IQueryable>. VD: query.ApplySort(o => o.OrderByDescending(x => x.CreatedAt));"}, {"returnType": "IQueryable<TResult>", "name": "LeftJoin", "generics": "TOuter, TInner, TKey, TResult", "params": ["this IQueryable<TOuter> outer", "IQueryable<TInner> inner", "Expression<Func<TOuter, TKey>> outerKeySelector", "Expression<Func<TInner, TKey>> innerKeySelector", "Expression<Func<TOuter, TInner?, TResult>> resultSelector"], "doc": "Left Join cho IQueryable (LINQ không có sẵn). VD: query.LeftJoin(_queryService.GetQueryable<Partner>(), a => a.UserId, b => b.Id, (a,b) => new {...})"}, {"returnType": "IQueryable<T>", "name": "Contains", "generics": "T, TKey", "params": ["this IQueryable<T> source", "Expression<Func<T, TKey>> selector", "IEnumerable<TKey>? values"], "doc": "Lọc \"chứa một trong các giá trị\" — tương đương TVP bên SQL Server: cả danh sách đi xuống DB trong MỘT tham số mảng (PostgreSQL sinh ra <c>= ANY(@p)</c>), không sinh mỗi giá trị một tham số. VD: <c>query.Contains(x => x.Id, groupIds)</c>. Danh sách rỗng ⇒ không bản ghi nào khớp."}, {"returnType": "IQueryable<T>", "name": "Contains", "generics": "T, TKey", "params": ["this IQueryable<T> source", "Expression<Func<T, TKey>> selector", "IEnumerable<TKey>? values", "QueryOptions options"], "doc": "Như trên, nhận cấu hình <see cref=\"QueryOptions\"/> (lọc trùng, số giá trị tối đa) — inject <c>IOptions&lt;QueryOptions&gt;</c> ở service rồi truyền <c>_queryOptions.Value</c>."}]}, {"class": "StringExtensions", "path": "src/Kindi.API.Application/Common/Extensions/StringExtensions.cs", "doc": "Extension cho string: so sánh không phân biệt hoa/thường và chuẩn hoá tiếng Việt.", "methods": [{"returnType": "bool", "name": "EqualsIgnoreCase", "generics": "", "params": ["this string? value", "string? other"], "doc": "Extension cho string: so sánh không phân biệt hoa/thường và chuẩn hoá tiếng Việt."}, {"returnType": "bool", "name": "ContainsIgnoreCase", "generics": "", "params": ["this string? source", "string? value"], "doc": "Extension cho string: so sánh không phân biệt hoa/thường và chuẩn hoá tiếng Việt."}, {"returnType": "bool", "name": "StartsWithIgnoreCase", "generics": "", "params": ["this string? source", "string? value"], "doc": "Extension cho string: so sánh không phân biệt hoa/thường và chuẩn hoá tiếng Việt."}, {"returnType": "bool", "name": "EndsWithIgnoreCase", "generics": "", "params": ["this string? source", "string? value"], "doc": "Extension cho string: so sánh không phân biệt hoa/thường và chuẩn hoá tiếng Việt."}, {"returnType": "string", "name": "RemoveVietnameseSign", "generics": "", "params": ["this string? value"], "doc": "So sánh bằng nhau không phân biệt hoa/thường (ordinal). public static bool EqualsIgnoreCase(this string? value, string? other) => string.Equals(value, other, StringComparison.OrdinalIgnoreCase); Kiểm tra chứa chuỗi con, không phân biệt hoa/thường (ordinal). public static bool ContainsIgnoreCase(this string? source, string? value) => !string.IsNullOrEmpty(source) && !string.IsNullOrEmpty(value) && source.Contains(value, StringComparison.OrdinalIgnoreCase); Kiểm tra bắt đầu bằng, không phân biệt hoa/thường (ordinal). public static bool StartsWithIgnoreCase(this string? source, string? value) => !string.IsNullOrEmpty(source) && !string.IsNullOrEmpty(value) && source.StartsWith(value, StringComparison.OrdinalIgnoreCase); Kiểm tra kết thúc bằng, không phân biệt hoa/thường (ordinal). public static bool EndsWithIgnoreCase(this string? source, string? value) => !string.IsNullOrEmpty(source) && !string.IsNullOrEmpty(value) && source.EndsWith(value, StringComparison.OrdinalIgnoreCase); Bỏ dấu tiếng Việt (Sữa bột → Sua bot), giữ nguyên chữ và khoảng trắng."}, {"returnType": "string", "name": "ToSearchKey", "generics": "", "params": ["this string? value"], "doc": "Khoá tìm kiếm trong bộ nhớ: bỏ dấu tiếng Việt, viết thường, gộp khoảng trắng."}, {"returnType": "string?", "name": "NormalizeSearchFilter", "generics": "", "params": ["this string? value"], "doc": "Chuẩn hoá từ khoá lọc do client gửi lên: bỏ khoảng trắng thừa và các giá trị giữ chỗ (undefined/null/nan/all) coi như không lọc."}, {"returnType": "string", "name": "ToLikeEscaped", "generics": "", "params": ["this string? value"], "doc": "Escape ký tự đại diện trong từ khoá tìm kiếm: \\, % và _ (dùng cho mẫu LIKE/ILIKE dưới DB). Chỉ trả về từ khoá đã escape, KHÔNG bọc sẵn hai dấu % — phía truy vấn tự ghép \"%\" + term + \"%\" ngay trong biểu thức để EF dịch thành chuỗi nối dưới SQL. LƯU Ý: Npgsql sinh ILIKE mặc định là ESCAPE '' (TẮT escape), nên khi dùng từ khoá đã escape bắt buộc truyền escape char: EF.Functions.ILike(col, pattern, \"\\\\\")."}]}, {"class": "StringQueryExtensions", "path": "src/Kindi.API.Application/Common/Extensions/StringQueryExtensions.cs", "doc": "Tìm kiếm chuỗi NGAY TRONG truy vấn EF, viết gọn ở chỗ gọi: <code>x.ProductName.Like(keyword)</code> thay cho <c>EF.Functions.ILike(KindiDbFunctions.Unaccent(x.ProductName), \"%\" + keyword + \"%\", \"\\\\\")</c> lặp đi lặp lại ở mọi trường tìm kiếm. <para> Ở tầng DB, <see cref=\"Like\"/> được dịch thành <c>strpos(lower(unaccent(col)), lower(unaccent(từ khoá))) &gt; 0</c> — bỏ dấu tiếng Việt cả hai vế, không phân biệt hoa/thường, và từ khoá được hiểu NGUYÊN VĂN nên KHÔNG cần escape <c>%</c>/<c>_</c> ở chỗ gọi (xem <c>KindiModelBuilderExtensions.ConfigureKindiModel</c>). </para> <para> MÃ (code) thì KHÔNG dùng <see cref=\"Like\"/>: mã là duy nhất và có index, dùng <see cref=\"EqualsCode\"/> để câu truy vấn chỉ so bằng <c>=</c> và còn dùng được index. </para>", "methods": [{"returnType": "bool", "name": "Like", "generics": "", "params": ["this string? value", "string? keyword"], "doc": "Ký tự thoát cho <c>%</c> và <c>_</c> của phép LIKE — chỉ còn dùng cho câu truy vấn cũ. public const string LikeEscape = \"\\\\\"; Tìm CHỨA từ khoá, bỏ dấu tiếng Việt và không phân biệt hoa/thường — dùng cho tên, mô tả, nội dung. Ngoài truy vấn EF (ví dụ test in-memory) chạy bằng so khớp chuỗi con đã bỏ dấu."}, {"returnType": "bool", "name": "EqualsCode", "generics": "", "params": ["this string? value", "string? code"], "doc": "So khớp ĐÚNG giá trị của một cột MÃ: từ khoá được chuẩn hoá hoa/thường ngay ở tham số nên cột giữ nguyên và index vẫn dùng được. Mã là duy nhất nên tìm một phần phải dùng <see cref=\"Like\"/>."}, {"returnType": "bool", "name": "SameText", "generics": "", "params": ["this string? value", "string? text"], "doc": "So khớp ĐÚNG một giá trị chữ (không tìm một phần) mà vẫn bỏ dấu tiếng Việt + không phân biệt hoa/thường, ví dụ kiểm tra trùng tên công ty. Phải bỏ dấu cả hai vế nên câu SQL không dùng được index — chỉ dùng cho câu kiểm tra duy nhất, không dùng cho danh sách."}]}, {"class": "AuditLogDeletionRules", "path": "src/Kindi.API.Application/Common/Helpers/AuditLogDeletionRules.cs", "doc": "true = xoá theo lựa chọn; false = xoá theo khoảng ngày. public bool IsBySelection => Ids.Count > 0; } Quy tắc xoá nhật ký hoạt động — bảng nhật ký là append-only (không có xoá mềm) nên xoá là XOÁ THẬT. Luôn bắt buộc có điều kiện: chọn Id hoặc khoảng ngày, tránh xoá sạch nhật ký do thiếu tham số.", "methods": [{"returnType": "AuditLogDeleteScope", "name": "Resolve", "generics": "", "params": ["IEnumerable<Guid>? ids", "DateTime? fromDate", "DateTime? toDate"], "doc": "Số dòng tối đa cho một lần xoá theo lựa chọn (chặn payload quá lớn). public const int MaxIdsPerRequest = 1000; Dựng phạm vi xoá từ yêu cầu: có Id thì xoá theo lựa chọn (bỏ Id rỗng, bỏ trùng); không có Id thì buộc phải có ít nhất một mốc ngày."}, {"returnType": "IQueryable<AuditLog>", "name": "Apply", "generics": "", "params": ["IQueryable<AuditLog> query", "AuditLogDeleteScope scope"], "doc": "Số dòng tối đa cho một lần xoá theo lựa chọn (chặn payload quá lớn). public const int MaxIdsPerRequest = 1000; Dựng phạm vi xoá từ yêu cầu: có Id thì xoá theo lựa chọn (bỏ Id rỗng, bỏ trùng); không có Id thì buộc phải có ít nhất một mốc ngày."}, {"returnType": "IQueryable<AuthAuditLog>", "name": "Apply", "generics": "", "params": ["IQueryable<AuthAuditLog> query", "AuditLogDeleteScope scope"], "doc": "Số dòng tối đa cho một lần xoá theo lựa chọn (chặn payload quá lớn). public const int MaxIdsPerRequest = 1000; Dựng phạm vi xoá từ yêu cầu: có Id thì xoá theo lựa chọn (bỏ Id rỗng, bỏ trùng); không có Id thì buộc phải có ít nhất một mốc ngày."}, {"returnType": "string", "name": "Describe", "generics": "", "params": ["AuditLogDeleteScope scope"], "doc": "Số dòng tối đa cho một lần xoá theo lựa chọn (chặn payload quá lớn). public const int MaxIdsPerRequest = 1000; Dựng phạm vi xoá từ yêu cầu: có Id thì xoá theo lựa chọn (bỏ Id rỗng, bỏ trùng); không có Id thì buộc phải có ít nhất một mốc ngày."}]}, {"class": "BusinessGroupSearchFilters", "path": "src/Kindi.API.Application/Common/Helpers/BusinessGroupSearchFilters.cs", "doc": "Lọc danh sách nhóm theo từ khoá. Khi client truyền <see cref=\"BusinessGroupSearchField\"/> thì CHỈ dò đúng một trường (tránh OR lan sang các cột khác); bỏ trống thì giữ nguyên tập trường mặc định của từng danh sách.", "methods": [{"returnType": "IQueryable<BusinessGroup>", "name": "ApplyField", "generics": "", "params": ["IQueryable<BusinessGroup> query", "string? searchTerm", "BusinessGroupSearchField? searchField"], "doc": "Tên các trường hợp lệ cho tham số <c>searchField</c> (dùng cho tài liệu/UI). public static readonly IReadOnlyList<string> ValidFieldNames = new[] { \"name\", \"description\", \"topic\", \"businessFieldName\", \"code\" }; Lọc theo đúng một trường khi client chỉ định. <paramref name=\"searchTerm\"/> là từ khoá thô (Like() tự bỏ dấu và không phân biệt hoa/thường ở tầng DB); từ khoá rỗng hoặc không chỉ định trường thì trả về nguyên trạng."}]}, {"class": "CodeGenerator", "path": "src/Kindi.API.Application/Common/Helpers/CodeGenerator.cs", "doc": "Sinh mã tham chiếu tự động theo format \"{PREFIX}-{random}\". Toàn bộ in hoa, độ dài ≤ 30 ký tự, bỏ các ký tự dễ nhầm (0/O/1/I).", "methods": [{"returnType": "string", "name": "Generate", "generics": "", "params": ["string prefix", "int randomLength = 6"], "doc": "Sinh code dạng \"{prefix}-XXXXXX\" (in hoa)."}, {"returnType": "async Task<string>", "name": "GenerateUniqueAsync", "generics": "T", "params": ["IQueryService queryService", "string prefix", "Expression<Func<T, bool>> codeExists", "CancellationToken cancellationToken = default"], "doc": "Sinh code cộng với việc kiểm tra unique theo predicate. Tối đa 5 lần thử, nếu hết vẫn báo lỗi để tránh vô hạn."}]}, {"class": "DateRangeBounds", "path": "src/Kindi.API.Application/Common/Helpers/DateRangeBounds.cs", "doc": "Chuẩn hoá khoảng ngày dùng cho bộ lọc và thao tác xoá: UI gửi ngày dạng YYYY-MM-DD nên mốc KẾT THÚC phải phủ hết ngày đó — nếu không, bản ghi phát sinh trong chính ngày kết thúc sẽ bị loại (lỗi \"lọc tới 06/10 mà không thấy log của ngày 06/10\").", "methods": [{"returnType": "DateTime?", "name": "NormalizeFrom", "generics": "", "params": ["DateTime? value"], "doc": "Chuẩn hoá khoảng ngày dùng cho bộ lọc và thao tác xoá: UI gửi ngày dạng YYYY-MM-DD nên mốc KẾT THÚC phải phủ hết ngày đó — nếu không, bản ghi phát sinh trong chính ngày kết thúc sẽ bị loại (lỗi \"lọc tới 06/10 mà không thấy log của ngày 06/10\")."}, {"returnType": "DateTime?", "name": "NormalizeTo", "generics": "", "params": ["DateTime? value"], "doc": "Mốc bắt đầu: chỉ quy về UTC, giữ nguyên phần giờ nếu client gửi kèm. public static DateTime? NormalizeFrom(DateTime? value) => value?.ToUniversalTime(); Mốc kết thúc: nếu client chỉ gửi NGÀY (00:00:00) thì lấy hết ngày đó (23:59:59.9999999 giờ địa phương → UTC); gửi kèm giờ thì giữ nguyên."}]}, {"class": "KindiDbFunctions", "path": "src/Kindi.API.Application/Common/Helpers/KindiDbFunctions.cs", "doc": "Hàm dưới DB dùng trong truy vấn EF (không gọi trực tiếp được ở C#).", "methods": [{"returnType": "string", "name": "Unaccent", "generics": "", "params": ["string value"], "doc": "Bỏ dấu tiếng Việt ngay trong câu truy vấn (extension <c>unaccent</c> của PostgreSQL), nhờ đó tìm \"sua bot\" vẫn ra \"Sữa bột\"."}]}, {"class": "PurgeRules", "path": "src/Kindi.API.Application/Common/Helpers/PurgeRules.cs", "doc": "true = xoá theo lựa chọn; false = xoá theo khoảng ngày. public bool IsBySelection => Ids.Count > 0; } Quy tắc xoá vĩnh viễn ở màn \"Đã xoá\": luôn bắt buộc có điều kiện (chọn dòng hoặc khoảng ngày) và CHỈ áp lên bản ghi đã xoá mềm — màn thường chỉ được xoá mềm.", "methods": [{"returnType": "PurgeScope", "name": "Resolve", "generics": "", "params": ["IEnumerable<Guid>? ids", "DateTime? fromDate", "DateTime? toDate"], "doc": "Số dòng tối đa cho một lần xoá theo lựa chọn. public const int MaxIdsPerRequest = 500; Dựng phạm vi xoá từ yêu cầu: có Id thì xoá theo lựa chọn (bỏ Id rỗng, bỏ trùng); không có Id thì buộc phải có ít nhất một mốc ngày."}, {"returnType": "IQueryable<T>", "name": "Apply", "generics": "T", "params": ["IQueryable<T> query", "PurgeScope scope"], "doc": "Lọc đúng các bản ghi sẽ xoá vĩnh viễn: bắt buộc đang ở trạng thái ĐÃ XOÁ MỀM, rồi lọc theo lựa chọn hoặc theo khoảng ngày xoá mềm."}, {"returnType": "string", "name": "Describe", "generics": "", "params": ["PurgeScope scope"], "doc": "Lọc đúng các bản ghi sẽ xoá vĩnh viễn: bắt buộc đang ở trạng thái ĐÃ XOÁ MỀM, rồi lọc theo lựa chọn hoặc theo khoảng ngày xoá mềm."}]}, {"class": "RequestSearchFilters", "path": "src/Kindi.API.Application/Common/Helpers/RequestSearchFilters.cs", "doc": "Lọc danh sách yêu cầu theo từ khoá. Khi client truyền <see cref=\"RequestSearchField\"/> thì CHỈ dò đúng một trường (tránh OR lan sang các cột khác gây truy vấn nặng và kết quả khó hiểu); bỏ trống thì dò trên mọi trường như trước. <para> Bản ghi chỉ lưu MÃ người giới thiệu, không lưu tên — nên khi tìm theo TÊN người giới thiệu (<see cref=\"RequestSearchField.RecordReferrerName\"/> / <see cref=\"RequestSearchField.AccountReferrerName\"/>), caller phải quy tên về tập mã trước (xem <c>IReferralService.FindReferrerCodesByNameAsync</c>) rồi truyền vào <c>referrerNameCodes</c>. Danh sách rỗng nghĩa là không khớp bản ghi nào. </para>", "methods": [{"returnType": "IQueryable<OfferRequest>", "name": "ApplyOffer", "generics": "", "params": ["IQueryable<OfferRequest> query", "string? search", "RequestSearchField? searchField", "IReadOnlyCollection<string>? referrerNameCodes = null"], "doc": "Tên các trường hợp lệ cho tham số <c>searchField</c> (dùng cho tài liệu/UI). public static readonly IReadOnlyList<string> ValidFieldNames = new[] { \"productName\", \"code\", \"recordReferrerCode\", \"customerName\", \"customerPhone\", \"customerEmail\", \"recordReferrerName\", \"accountReferrerName\" }; Lọc danh sách yêu cầu nhận offer. <paramref name=\"search\"/> đã được trim; tìm theo kiểu chứa. <paramref name=\"referrerNameCodes\"/> là tập mã chia sẻ của những người có tên khớp từ khoá (dùng cho <see cref=\"RequestSearchField.RecordReferrerName\"/> / <see cref=\"RequestSearchField.AccountReferrerName\"/>)."}, {"returnType": "IQueryable<PurchaseRequest>", "name": "ApplyPurchase", "generics": "", "params": ["IQueryable<PurchaseRequest> query", "string? searchTerm", "RequestSearchField? searchField", "IReadOnlyCollection<string>? referrerNameCodes = null"], "doc": "Lọc danh sách yêu cầu mua. <paramref name=\"searchTerm\"/> là từ khoá thô (Like() tự bỏ dấu + không phân biệt hoa/thường). <paramref name=\"referrerNameCodes\"/> là tập mã chia sẻ của những người có tên khớp từ khoá (dùng cho tên người giới thiệu)."}, {"returnType": "IQueryable<GroupBuyingRequest>", "name": "ApplyGroupBuying", "generics": "", "params": ["IQueryable<GroupBuyingRequest> query", "string? searchTerm", "RequestSearchField? searchField", "IReadOnlyCollection<string>? referrerNameCodes = null"], "doc": "Lọc danh sách yêu cầu mua chung. <paramref name=\"searchTerm\"/> là từ khoá thô (Like() tự bỏ dấu + không phân biệt hoa/thường). Người mở nhóm nằm ở bảng Users nên tên/SĐT/email lấy qua quan hệ <c>User</c>. <paramref name=\"referrerNameCodes\"/> là tập mã chia sẻ của những người có tên khớp từ khoá (dùng cho tên người giới thiệu)."}]}, {"class": "RevenueExpenseHelper", "path": "src/Kindi.API.Application/Common/Helpers/RevenueExpenseHelper.cs", "doc": "Tiện ích tính chi phí phát sinh của bản khai doanh thu. Chi phí phát sinh bằng tổng các dòng chi phí quản trị viên nhập; tách riêng ở đây để phép cộng tiền có test chốt.", "methods": [{"returnType": "decimal", "name": "Total", "generics": "", "params": ["IEnumerable<TransactionExpenseRequest>? lines"], "doc": "Tiện ích tính chi phí phát sinh của bản khai doanh thu. Chi phí phát sinh bằng tổng các dòng chi phí quản trị viên nhập; tách riêng ở đây để phép cộng tiền có test chốt."}]}, {"class": "UserInfo", "path": "src/Kindi.API.Application/Common/Helpers/UserInfo.cs", "doc": "Quy tắc hiển thị thông tin cá nhân lấy từ bảng <c>Users</c>.", "methods": [{"returnType": "bool", "name": "IsPlaceholderEmail", "generics": "", "params": ["string? email", "string? phone"], "doc": "Email tạm mà hệ thống sinh cho tài khoản tạo tự động (<c>{sđt}@temp.com</c>) — coi như người dùng chưa nhập email, không trả ra UI."}, {"returnType": "string?", "name": "DisplayEmail", "generics": "", "params": ["string? email", "string? phone"], "doc": "Email tạm mà hệ thống sinh cho tài khoản tạo tự động (<c>{sđt}@temp.com</c>) — coi như người dùng chưa nhập email, không trả ra UI."}]}];

